#include <assert.h>

#define SUID_DUMP_DISABLE 0
#define SUID_DUMP_USER    1
#define SUID_DUMP_ROOT    2

/* kernel/ptrace.c __ptrace_may_access: returns 1 if access is permitted. */
static int old_ptrace_allows(int dumpable, int has_cap)
{
	/* if (!dumpable && !has_cap) return -EPERM; else allow */
	return !(!dumpable && !has_cap);
}
static int new_ptrace_allows(int dumpable, int has_cap)
{
	/* if (dumpable != SUID_DUMP_USER && !has_cap) return -EPERM; else allow */
	return !(dumpable != SUID_DUMP_USER && !has_cap);
}

/* arch/ia64 start_thread: returns 1 if scratch registers are zapped. */
static int old_ia64_zaps(int dumpable) { return !dumpable; }
static int new_ia64_zaps(int dumpable) { return (dumpable != SUID_DUMP_USER); }

int main(void)
{
	int values[3] = { SUID_DUMP_DISABLE, SUID_DUMP_USER, SUID_DUMP_ROOT };
	int i, fails = 0;

	printf("ptrace gate (has_cap=0: access must be denied):\n");
	for (i = 0; i < 3; i++) {
		int v = values[i];
		printf("  dumpable=%d old_allows=%d new_allows=%d\n",
		       v, old_ptrace_allows(v, 0), new_ptrace_allows(v, 0));
		if (v == SUID_DUMP_USER) {
			if (!old_ptrace_allows(v, 0) || !new_ptrace_allows(v, 0)) {
				printf("  FAIL: USER must be allowed\n"); fails++;
			}
		} else {
			if (old_ptrace_allows(v, 0)) {
				printf("  (old bug reproduced for dumpable=%d)\n", v);
			}
			if (new_ptrace_allows(v, 0)) {
				printf("  FAIL: new code still allows dumpable=%d\n", v); fails++;
			}
		}
	}
	/* capability holder is always allowed by both */
	for (i = 0; i < 3; i++) {
		int v = values[i];
		if (!old_ptrace_allows(v, 1) || !new_ptrace_allows(v, 1)) {
			printf("  FAIL: cap holder denied for dumpable=%d\n", v); fails++;
		}
	}

	printf("ia64 register scrub (must zap unless SUID_DUMP_USER):\n");
	for (i = 0; i < 3; i++) {
		int v = values[i];
		printf("  dumpable=%d old_zaps=%d new_zaps=%d\n",
		       v, old_ia64_zaps(v), new_ia64_zaps(v));
		if (v == SUID_DUMP_USER) {
			if (old_ia64_zaps(v) || new_ia64_zaps(v)) {
				printf("  FAIL: USER must not zap\n"); fails++;
			}
		} else {
			if (!old_ia64_zaps(v)) {
				printf("  (old bug reproduced for dumpable=%d)\n", v);
